def parse(line):
    fields = []
    buf = []
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < n and line[i+1] == '"':
                    buf.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                buf.append(ch)
        elif ch == '"':
            in_quotes = True
        elif ch == ',':
            fields.append(''.join(buf).strip())
            buf = []
        else:
            buf.append(ch)
        i += 1
    fields.append(''.join(buf).strip())
    if len(fields) != 3:
        return None
    return fields

